from typing import Any


def decode_scan(metadata: dict[str, Any], values: list[float] | tuple[float, ...]) -> list[list[list[float]]]:
    if not isinstance(metadata, dict):
        raise ValueError("metadata must be a dictionary")
    if any(key not in metadata for key in ("rows", "columns", "channels", "layout")):
        raise ValueError("metadata is missing required keys")
    rows, columns, channels = metadata["rows"], metadata["columns"], metadata["channels"]
    if any(not isinstance(value, int) or isinstance(value, bool) or value < 0 for value in (rows, columns, channels)):
        raise ValueError("dimensions must be non-negative integers")
    if metadata["layout"] not in {"BIP", "BIL", "BSQ"}:
        raise ValueError("unsupported layout")
    if not isinstance(values, (list, tuple)):
        raise ValueError("values must be a list or tuple")
    if any(not isinstance(value, (int, float)) or isinstance(value, bool) for value in values):
        raise ValueError("samples must be numeric")
    if len(values) != rows * columns * channels:
        raise ValueError("sample count does not match dimensions")

    cube = [[[0 for _ in range(channels)] for _ in range(columns)] for _ in range(rows)]
    for row in range(rows):
        for column in range(columns):
            for channel in range(channels):
                if metadata["layout"] == "BIP":
                    index = (row * columns + column) * channels + channel
                elif metadata["layout"] == "BIL":
                    index = (row * columns + column) * channels + channel
                else:
                    index = (channel * rows + row) * columns + column
                cube[row][column][channel] = values[index]
    return cube
```

