import unittest
from solution import decode_scan


class DecodeScanTests(unittest.TestCase):
    def test_bip_layout(self):
        metadata = {"rows": 2, "columns": 2, "channels": 2, "layout": "BIP", "extra": 1}
        values = [0, 1, 2, 3, 4, 5, 6, 7]
        self.assertEqual(decode_scan(metadata, values),
                         [[[0, 1], [2, 3]], [[4, 5], [6, 7]]])
        self.assertEqual(values, list(range(8)))

    def test_bil_layout_columns_fastest_within_channel(self):
        metadata = {"rows": 2, "columns": 2, "channels": 2, "layout": "BIL"}
        values = [0, 2, 1, 3, 4, 6, 5, 7]
        self.assertEqual(decode_scan(metadata, values),
                         [[[0, 1], [2, 3]], [[4, 5], [6, 7]]])

    def test_bsq_layout(self):
        metadata = {"rows": 2, "columns": 2, "channels": 2, "layout": "BSQ"}
        values = [0, 2, 4, 6, 1, 3, 5, 7]
        self.assertEqual(decode_scan(metadata, values),
                         [[[0, 1], [2, 3]], [[4, 5], [6, 7]]])

    def test_zero_dimension_shapes(self):
        self.assertEqual(decode_scan({"rows": 0, "columns": 3, "channels": 2, "layout": "BIP"}, []), [])
        self.assertEqual(decode_scan({"rows": 2, "columns": 0, "channels": 3, "layout": "BIL"}, []), [[], []])
        self.assertEqual(decode_scan({"rows": 2, "columns": 3, "channels": 0, "layout": "BSQ"}, []),
                         [[[], [], []], [[], [], []]])

    def test_malformed_inputs(self):
        valid = {"rows": 1, "columns": 1, "channels": 1, "layout": "BIP"}
        cases = [
            (None, [1]), ({"rows": 1}, [1]),
            ({**valid, "rows": True}, [1]), ({**valid, "columns": -1}, []),
            ({**valid, "channels": 1.0}, [1]), ({**valid, "layout": "XYZ"}, [1]),
            (valid, {"x": 1}), (valid, [True]), (valid, ["1"]), (valid, []),
        ]
        for metadata, values in cases:
            with self.subTest(metadata=metadata, values=values):
                with self.assertRaises(ValueError):
                    decode_scan(metadata, values)


if __name__ == "__main__":
    unittest.main()

